var o=[{title:`Como surge a carga`,text:`Estar de pé com uma barra sobre os ombros ou segurar um peso acima da cabeça pode aumentar as forças transmitidas pelo tronco e pela coluna. As caminhadas pesadas com carga e alguns exercícios de puxada também exigem uma forte estabilidade do tronco. A força real sobre a coluna depende da posição do corpo, do esforço muscular, da alavanca e da direção da resistência, por isso uma barra nos ombros é apenas parte do quadro.`},{title:`Geralmente seguro para pessoas saudáveis`,text:`A sua coluna é carregada durante o movimento do dia a dia e pode adaptar-se a exercício com progressão gradual. Para quem treina e é saudável, a carga axial não é insegura em si. Importa mais quando tem uma restrição médica, um sintoma novo ou uma preferência pessoal por reduzir a compressão.`},{title:`Escolher alternativas`,text:`Um agachamento goblet, um split squat ou um exercício em máquina com apoio carregam o corpo de forma diferente de um agachamento pesado com barra nas costas. Um exercício de core no chão pode ajudar quando as caminhadas com carga em pé não lhe convêm. Nenhum substituto elimina por completo a carga na coluna.`},{title:`Progrida com cuidado`,text:`Aprenda a estabilizar e a controlar o movimento, use cargas que correspondam à sua capacidade atual e altere uma variável de treino de cada vez. Não tem de fazer um exercício de grande compressão só porque é tradicional no treino de força.`},{title:`Usar o TrainUp`,text:`Se quiser limitar a carga na coluna, acrescente as costas como limitação no Perfil, com uma nota. O plano escolhe apenas exercícios que se adaptam às suas limitações. Escolher exercícios de menor carga não trata a dor nas costas nem substitui o aconselhamento médico.`}];var r=[{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NHS: dor lombar e sinais de alerta urgentes`,url:`https://www.nhs.uk/conditions/back-pain/`}];var s={sections:o,sources:r};export{s as default,o as sections,r as sources};